additionalExercises.referenceSolution:
#include <iostream>
#include <memory>
#include <vector>
#include <utility>
#include <string>

struct Box { int* p; explicit Box(int x): p(new int(x)) {} Box(const Box& x): p(new int(*x.p)) {} Box& operator=(const Box&) = delete; ~Box() { delete p; } };
int solve(int a, int b) { int saved; { Box first{a}; { Box second = first; *second.p = b; saved = *second.p; } } return saved + a - b + b; }
